1	import 'package:cerne/core/design_tokens.dart';
2	import 'package:cerne/features/chat/domain/entities/bookmark_status.dart';
3	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
4	import 'package:cerne/features/chat/presentation/widgets/bookmark_button.dart';
5	import 'package:cerne/features/chat/presentation/widgets/chat_message_bubble.dart';
6	import 'package:flutter/material.dart';
7	import 'package:flutter_test/flutter_test.dart';
8	
9	ChatMessage _buildMessage({
10	  required ChatMessageStatus status,
11	  ChatRole role = ChatRole.assistant,
12	  String content = 'hello',
13	  DateTime? createdAt,
14	}) => ChatMessage(
15	  id: 'm1',
16	  sessionId: 's1',
17	  role: role,
18	  content: content,
19	  seq: 0,
20	  status: status,
21	  retryCount: 0,
22	  createdAt: createdAt ?? DateTime(2026, 1, 1, 10, 30),
23	);
24	
25	Future<void> pumpBubble(
26	  WidgetTester tester,
27	  ChatMessage message, {
28	  VoidCallback? onRetryTap,
29	  BookmarkStatus? bookmarkStatus,
30	  VoidCallback? onBookmarkTap,
31	}) {
32	  return tester.pumpWidget(
33	    MaterialApp(
34	      home: Scaffold(
35	        body: ChatMessageBubble(
36	          message: message,
37	          onRetryTap: onRetryTap,
38	          bookmarkStatus: bookmarkStatus,
39	          onBookmarkTap: onBookmarkTap,
40	        ),
41	      ),
42	    ),
43	  );
44	}
45	
46	void main() {
47	  testWidgets(
48	    'a streaming message renders an inline blinking cursor at the end of '
49	    'its text, no spinner below the bubble, and is not tappable',
50	    (tester) async {
51	      var tapped = false;
52	      await pumpBubble(
53	        tester,
54	        _buildMessage(status: ChatMessageStatus.streaming),
55	        onRetryTap: () => tapped = true,
56	      );
57	
58	      expect(find.byType(CircularProgressIndicator), findsNothing);
59	      final richText = tester.widget<Text>(find.byType(Text));
60	      final span = richText.textSpan! as TextSpan;
61	      expect(span.text, 'hello');
62	      expect(span.children, hasLength(1));
63	      expect(span.children!.single, isA<WidgetSpan>());
64	
65	      await tester.tap(find.byType(GestureDetector));
66	      await tester.pump();
67	      expect(tapped, isFalse);
68	    },
69	  );
70	
71	  testWidgets('an empty streaming message still renders only the blinking cursor', (
72	    tester,
73	  ) async {
74	    await pumpBubble(tester, _buildMessage(status: ChatMessageStatus.streaming, content: ''));
75	
76	    final richText = tester.widget<Text>(find.byType(Text));
77	    final span = richText.textSpan! as TextSpan;
78	    expect(span.text, '');
79	    expect(span.children, hasLength(1));
80	    expect(span.children!.single, isA<WidgetSpan>());
81	  });
82	
83	  testWidgets('a complete message renders its final text + timestamp with no indicator', (
84	    tester,
85	  ) async {
86	    await pumpBubble(tester, _buildMessage(status: ChatMessageStatus.complete, content: 'oi!'));
87	
88	    expect(find.text('oi!'), findsOneWidget);
89	    expect(find.byType(CircularProgressIndicator), findsNothing);
90	    expect(find.textContaining('Falha'), findsNothing);
91	  });
92	
93	  testWidgets(
94	    'a failed message renders "Falha ao gerar resposta" in colorError, '
95	    'regular (not monospaced) font, with the timestamp still below it '
96	    '(prototype: the note sits above the time, not in its place)',
97	    (tester) async {
98	      await pumpBubble(tester, _buildMessage(status: ChatMessageStatus.failed));
99	
100	      final finder = find.textContaining('Falha ao gerar resposta');
101	      expect(finder, findsOneWidget);
102	      final text = tester.widget<Text>(finder);
103	      expect(text.style?.color, DesignTokens.colorError);
104	      expect(text.style?.fontFamily, DesignTokens.textBodyMd.fontFamily);
105	      expect(text.style?.fontSize, 12);
106	
107	      final context = tester.element(find.byType(Scaffold));
108	      final expectedLabel = TimeOfDay.fromDateTime(
109	        _buildMessage(status: ChatMessageStatus.failed).createdAt.toLocal(),
110	      ).format(context);
111	      expect(find.text(expectedLabel), findsOneWidget);
112	    },
113	  );
114	
115	  testWidgets('tapping a failed bubble invokes onRetryTap exactly once', (tester) async {
116	    var tapCount = 0;
117	    await pumpBubble(
118	      tester,
119	      _buildMessage(status: ChatMessageStatus.failed),
120	      onRetryTap: () => tapCount++,
121	    );
122	
123	    await tester.tap(find.text('hello'));
124	    await tester.pump();
125	
126	    expect(tapCount, 1);
127	  });
128	
129	  testWidgets(
130	    'a UTC createdAt (as returned by the backend for a history-loaded '
131	    'message) renders the local wall-clock time, same as the current '
132	    "device's own local DateTime would — not the raw UTC hour",
133	    (tester) async {
134	      final utcCreatedAt = DateTime.utc(2026, 1, 1, 23, 20);
135	      await pumpBubble(
136	        tester,
137	        _buildMessage(status: ChatMessageStatus.complete, createdAt: utcCreatedAt),
138	      );
139	
140	      final context = tester.element(find.byType(Scaffold));
141	      final expectedLabel = TimeOfDay.fromDateTime(utcCreatedAt.toLocal()).format(context);
142	
143	      expect(find.text(expectedLabel), findsOneWidget);
144	    },
145	  );
146	
147	  testWidgets('tapping a streaming/complete bubble invokes nothing', (tester) async {
148	    var tapCount = 0;
149	    await pumpBubble(
150	      tester,
151	      _buildMessage(status: ChatMessageStatus.complete),
152	      onRetryTap: () => tapCount++,
153	    );
154	
155	    await tester.tap(find.text('hello'));
156	    await tester.pump();
157	
158	    expect(tapCount, 0);
159	  });
160	
161	  group('bookmark (US1/US4)', () {
162	    testWidgets(
163	      'a user-message bubble built with bookmarkStatus renders a '
164	      'BookmarkButton reflecting that status, laid out in a Row beside the '
165	      'bubble',
166	      (tester) async {
167	        await pumpBubble(
168	          tester,
169	          _buildMessage(status: ChatMessageStatus.complete, role: ChatRole.user),
170	          bookmarkStatus: BookmarkStatus.idle,
171	        );
172	
173	        expect(find.byType(BookmarkButton), findsOneWidget);
174	        expect(find.byType(Row), findsOneWidget);
175	        final button = tester.widget<BookmarkButton>(find.byType(BookmarkButton));
176	        expect(button.status, BookmarkStatus.idle);
177	      },
178	    );
179	
180	    testWidgets('bookmarkStatus: saved renders a BookmarkButton(status: saved)', (
181	      tester,
182	    ) async {
183	      await pumpBubble(
184	        tester,
185	        _buildMessage(status: ChatMessageStatus.complete, role: ChatRole.user),
186	        bookmarkStatus: BookmarkStatus.saved,
187	      );
188	
189	      final button = tester.widget<BookmarkButton>(find.byType(BookmarkButton));
190	      expect(button.status, BookmarkStatus.saved);
191	    });
192	
193	    testWidgets(
194	      'tapping the bookmark invokes onBookmarkTap, independently of '
195	      'onRetryTap',
196	      (tester) async {
197	        var bookmarkTaps = 0;
198	        var retryTaps = 0;
199	        await pumpBubble(
200	          tester,
201	          _buildMessage(status: ChatMessageStatus.complete, role: ChatRole.user),
202	          bookmarkStatus: BookmarkStatus.idle,
203	          onBookmarkTap: () => bookmarkTaps++,
204	          onRetryTap: () => retryTaps++,
205	        );
206	
207	        await tester.tap(find.byType(BookmarkButton));
208	        await tester.pump();
209	
210	        expect(bookmarkTaps, 1);
211	        expect(retryTaps, 0);
212	      },
213	    );
214	
215	    testWidgets(
216	      'the assistant branch never builds a BookmarkButton, for every '
217	      'ChatMessageStatus and regardless of bookmarkStatus/onBookmarkTap',
218	      (tester) async {
219	        for (final status in ChatMessageStatus.values) {
220	          await pumpBubble(
221	            tester,
222	            _buildMessage(status: status, role: ChatRole.assistant),
223	            bookmarkStatus: BookmarkStatus.saved,
224	            onBookmarkTap: () {},
225	          );
226	
227	          expect(find.byType(BookmarkButton), findsNothing);
228	        }
229	      },
230	    );
231	  });
232	}
